parameters.command:
uip ixp deployments get-taxonomy --folder-key "c4359cde-55f0-4f0e-9322-c6cdce74ab4c" "invoiceixp-cef0d447-ixp" --output json 2>&1 | python3 -c "
import json,sys
d=json.loads(sys.stdin.read())
if d.get('Result')=='Success':
    docTypes=d.get('Data',{}).get('documentTaxonomy',{}).get('documentTypes',[])
    for dt in docTypes:
        print(f'DocType: {dt.get(\"id\",\"?\")} / {dt.get(\"name\",\"?\")}')
        for f in dt.get('fields',[]):
            print(f'  Field: {f[\"fieldName\"]} ({f[\"type\"]})')
else:
    print('FAIL:', d.get('Message','?'), d.get('Instructions',''))
" 2>&1

uip ixp deployments get-taxonomy --folder-key "c4359cde-55f0-4f0e-9322-c6cdce74ab4c" --version 1 "invoiceixp-cef0d447-ixp" --output json 2>&1 | python3 -c "
import json,sys
d=json.loads(sys.stdin.read())
if d.get('Result')=='Success':
    docTypes=d.get('Data',{}).get('documentTaxonomy',{}).get('documentTypes',[])
    for dt in docTypes:
        print(f'DocType: {dt.get(\"id\",\"?\")} / {dt.get(\"name\",\"?\")}')
        for f in dt.get('fields',[]):
            print(f'  Field: {f[\"fieldName\"]} type={f[\"type\"]}')
else:
    print('FAIL:', d.get('Message','?'))
    print('INSTRUCTIONS:', d.get('Instructions',''))
" 2>&1

# Get IxP projects list to find the actual project name
uip ixp projects list --output json 2>&1 | python3 -c "
import json,sys
d=json.loads(sys.stdin.read())
if d.get('Result')=='Success':
    for p in d.get('Data',[]):
        print(f'  name={p.get(\"name\")} id={p.get(\"id\")}')
else:
    print('FAIL:', d.get('Message'))
" 2>&1

